_normal: .7;\n$opacity_full: 1;\n\n// menu round background hover feedback\n// good looking on dark AND white bg\n$action-background-hover: rgba(127, 127, 127, .25);\n\n// various structure data used in the\n// `NcAppNavigation` component\n$header-height: 50px;\n$navigation-width: 300px;\n\n// mobile breakpoint\n$breakpoint-mobile: 1024px;\n\n//messages list max width\n$messages-list-max-width: 800px;\n\n//message max width\n$message-max-width: 680px;\n\n//message utils width\n$message-utils-width: 100px;\n\n//message form max height\n$message-form-max-height: 180px;\n\n$color-call-background: rgba(34, 34, 34, 0.8);\n$color-guests-avatar: #ffffff;\n$color-background-guests-avatar: #b9b9b9;\n\n\n//chat font size\n$chat-font-size: 15px;\n\n//chat line height\n$chat-line-height: 1.6em;\n\n// fade transition\n$fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","\n\n@import '../../assets/variables';\n\n.scroller {\n\tpadding: 0 4px 0 6px;\n}\n\n.new-conversation {\n\tdisplay: flex;\n\tpadding: 8px 0 8px 12px;\n\talign-items: center;\n\n\t&--scrolled-down {\n\t\tborder-bottom: 1px solid var(--color-placeholder-dark);\n\t}\n}\n\n// Override vue overflow rules for <ul> elements within app-navigation\n.left-sidebar__list {\n\theight: 100% !important;\n\twidth: 100% !important;\n\toverflow-y: auto !important;\n\toverflow-x: hidden !important;\n\tpadding: 0;\n}\n\n.unread-mention-button {\n\tposition: absolute !important;\n\tleft: 50%;\n\ttransform: translateX(-50%);\n\tz-index: 100;\n\tbottom: 10px;\n\twhite-space: nowrap;\n}\n\n.conversations-search {\n\tflex-grow: 1;\n\n\t:deep(.input-field__input) {\n\t\tborder-radius: var(--border-radius-pill);\n\t}\n}\n\n.settings-button {\n\tjustify-content: flex-start !important;\n}\n\n:deep(.app-navigation ul) {\n\tpadding: 0 !important;\n}\n\n:deep(.app-navigation-toggle) {\n\ttop: 8px !important;\n\tright: -6px !important;\n}\n\n:deep(.app-navigation__list) {\n\tpadding: 0 !important;\n}\n"],"sourceRoot":""}]);
