// https://uxplanet.org/7-rules-for-mobile-ui-button-design-e9cf2ea54556\n// recommended is 48px\n// 44px is what we choose and have very good visual-to-usability ratio\n$clickable-area: 44px;\n\n// background icon size\n// also used for the scss icon font\n$icon-size: 16px;\n\n// icon padding for a $clickable-area width and a $icon-size icon\n// ( 44px - 16px ) / 2\n$icon-margin: math.div($clickable-area - $icon-size, 2);\n\n// transparency background for icons\n$icon-focus-bg: rgba(127, 127, 127, .25);\n\n// popovermenu arrow width from the triangle center\n$arrow-width: 9px;\n\n// opacities\n$opacity_disabled: .5;\n$opacity_normal: .7;\n$opacity_full: 1;\n\n// menu round background hover feedback\n// good looking on dark AND white bg\n$action-background-hover: rgba(127, 127, 127, .25);\n\n// various structure data used in the\n// `NcAppNavigation` component\n$header-height: 50px;\n$navigation-width: 300px;\n\n// mobile breakpoint\n$breakpoint-mobile: 1024px;\n\n//messages list max width\n$messages-list-max-width: 800px;\n\n//message max width\n$message-max-width: 680px;\n\n//message utils width\n$message-utils-width: 100px;\n\n//message form max height\n$message-form-max-height: 180px;\n\n$color-call-background: rgba(34, 34, 34, 0.8);\n$color-guests-avatar: #ffffff;\n$color-background-guests-avatar: #b9b9b9;\n\n\n//chat font size\n$chat-font-size: 15px;\n\n//chat line height\n$chat-line-height: 1.6em;\n\n// fade transition\n$fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","\n@import '../../assets/variables';\n\n.description {\n\tdisplay: flex;\n\twidth: 100%;\n\toverflow: hidden;\n\tposition: relative;\n\tmin-height: $clickable-area;\n\talign-items: flex-end;\n\n\t&__header {\n\t\tdisplay: flex;\n\t\talign-items: center;\n\t\tjustify-content: space-between;\n\t\theight: 44px;\n\t}\n\t&__title {\n\t\tcolor: var(--color-primary);\n\t\tfont-weight: bold;\n\t\tfont-size: var(--default-font-size);\n\t\tline-height: var(--default-line-height);\n\t}\n\n\t&__edit {\n\t\tmargin-left: 44px;\n\t}\n\n\t&__action {\n\t\tmargin: 0 0 4px 4px;\n\t}\n}\n\n.spinner {\n\twidth: $clickable-area;\n\theight: $clickable-area;\n\tmargin: 0 0 4px 44px;\n}\n\n.counter {\n\tbackground-color: var(--color-background-dark);\n\theight: 44px;\n\twidth: 44px;\n\tborder-radius: var(--border-radius-pill);\n\tposition: absolute;\n\ttop: 0;\n\tright: 0;\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n}\n\n// Restyle NcRichContenteditable component from our library.\n:deep(.rich-contenteditable__input) {\n\talign-self: flex-start;\n\tmin-height: var(--default-line-height);\n\tmax-height: unset;\n\tmargin: 12px 0 4px 0;\n\tpadding: 0 0 4px 0;\n\toverflow: visible;\n\twidth: 100% !important;\n\tbackground-color: transparent;\n\ttransition: $fade-transition;\n\t&::before {\n\t\tposition: relative;\n\t}\n\t&[contenteditable='false'] {\n\t\tbackground-color: transparent;\n\t\tcolor: var(--color-main-text);\n\t\tborder-color: transparent;\n\t\topacity: 1;\n\t\tborder-radius: 0;\n\t\tuser-select: text;\n\t}\n}\n\n"],"sourceRoot":""}]);
